146→// ReadTranscript reads the raw JSONL transcript bytes for a session.
147→func (c *CopilotCLIAgent) ReadTranscript(sessionRef string) ([]byte, error) {
148→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
149→	if err != nil {
150→		return nil, fmt.Errorf("failed to read transcript: %w", err)
151→	}
152→	return data, nil
153→}
